export type OwnershipHandoverStatus =
  | "pending"
  | "accepted"
  | "declined"
  | "canceled"
  | "expired";

export interface OwnershipHandover {
  readonly id: string;
  readonly orgId: OrgId;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly status: OwnershipHandoverStatus;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
  readonly resolvedAt: IsoTimestamp | null;
}

"member.removed": EventEnvelope & { memberId: MemberId; userId: UserId };
"organization.ownership_transferred": EventEnvelope & {
  fromUserId: UserId;
  toUserId: UserId;
};

export type ActivityAction =
  | "organization.updated"
  | "organization.ownership_transferred"

import { ZodError, type ZodIssue } from "zod";

/** Why an ownership offer was refused without changing the workspace. */
export type OwnershipHandoverRefusal =
  | "self"
  | "pending_exists"
  | "nothing_pending"
  | "expired";

/**
 * Raised when an ownership offer cannot be started or resolved. `reason`
 * distinguishes the four conflicts; `code` is what `toAppError` maps.
 */
export class OwnershipHandoverError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: OwnershipHandoverRefusal) {
    super(`Ownership handover refused: ${reason}`);
    this.name = "OwnershipHandoverError";
  }
}

