import type {
  Organization,
  OrganizationUsage,
  OwnershipHandover,
} from "@/types/organization";

export function toOwnershipHandover(row: OwnershipHandoverRow): OwnershipHandover {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    fromUserId: brandId<UserId>(row.fromUserId),
    toUserId: brandId<UserId>(row.toUserId),
    status: row.status,
    expiresAt: brandStamp(row.expiresAt),
    createdAt: brandStamp(row.createdAt),
    resolvedAt: brandStampOrNull(row.resolvedAt),
  };
}

export function toUsage(row: OrganizationUsageRow): OrganizationUsage {

/** Points the recorded owner at another user. Role rows are updated separately. */
export async function setOrgOwner(
  orgId: OrgId,
  ownerId: UserId,
): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set({ ownerId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {

/**
 * Ownership offers. An offer is open only while it is pending and its expiry
 * is still strictly in the future; lapse is computed, not stored.
 */
import { and, desc, eq, gt, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

const NEWEST_FIRST = [
  desc(ownershipHandovers.createdAt),
  desc(ownershipHandovers.id),
] as const;

export async function insertHandover(input: {
  orgId: OrgId;
  fromUserId: UserId;
  toUserId: UserId;
  createdAt: IsoTimestamp;
  expiresAt: IsoTimestamp;
}): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId: input.orgId,
      fromUserId: input.fromUserId,
      toUserId: input.toUserId,
      status: "pending",
      expiresAt: input.expiresAt,
      resolvedAt: null,
      createdAt: input.createdAt,
      updatedAt: input.createdAt,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/** The open offer for a workspace, if one can still be acted on. */
export async function findOpenHandover(
  orgId: OrgId,
  at: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, at),
      ),
    )
    .orderBy(...NEWEST_FIRST)
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/** Newest offer addressed to this user, whatever its status. */
export async function findLatestForUser(
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.toUserId, toUserId),
      ),
    )
    .orderBy(...NEWEST_FIRST)
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/**
 * Resolves a still-open offer. Returns null when the row is no longer pending
 * or its expiry is not strictly after `resolvedAt`.
 */
export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: Exclude<OwnershipHandoverStatus, "pending" | "expired">,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt, updatedAt: resolvedAt })
    .where(
      and(
        eq(ownershipHandovers.id, id),
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, resolvedAt),
      ),
    )
    .returning()
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/**
 * Withdraws every still-open offer that names `userId` on either side.
 * Called when that member leaves the workspace.
 */
export async function cancelOpenHandoversForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const resolvedAt = toIsoTimestamp(new Date());
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt, updatedAt: resolvedAt })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, resolvedAt),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}

