const NEWEST_FIRST = [
  desc(ownershipHandovers.createdAt),
  desc(ownershipHandovers.id),
] as const;

export async function insertHandover(input: {
  orgId: OrgId;
  fromUserId: UserId;
  toUserId: UserId;
  createdAt: IsoTimestamp;
  expiresAt: IsoTimestamp;
}): Promise<OwnershipHandover> {
