      orgId: input.orgId,
      fromUserId: input.fromUserId,
      toUserId: input.toUserId,
      status: "pending",
      expiresAt: input.expiresAt,
      resolvedAt: null,
      createdAt: input.createdAt,
      updatedAt: input.createdAt,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/** The open offer for a workspace, if one can still be acted on. */
export async function findOpenHandover(
  orgId: OrgId,
  at: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, at),
      ),
    )
    .orderBy(...NEWEST_FIRST)
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/** Newest offer addressed to this user, whatever its status. */
export async function findLatestForUser(
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.toUserId, toUserId),
      ),
    )
    .orderBy(...NEWEST_FIRST)
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/**
 * Resolves a still-open offer. Returns null when the row is no longer pending
 * or its expiry is not strictly after `resolvedAt`.
 */
export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: Exclude<OwnershipHandoverStatus, "pending" | "expired">,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt, updatedAt: resolvedAt })
    .where(
      and(
        eq(ownershipHandovers.id, id),
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, resolvedAt),
      ),
    )
    .returning()
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/**
 * Withdraws every still-open offer that names `userId` on either side.
 * Called when that member leaves the workspace.
 */
export async function cancelOpenHandoversForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const resolvedAt = toIsoTimestamp(new Date());
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt, updatedAt: resolvedAt })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
