export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

const HANDOVER_WINDOW_DAYS = 7;

/**
 * Offering and withdrawing follow the recorded owner (`ownerId`), not the
 * owner role. A second member who merely holds that role is refused.
 */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (actor.userId === org.ownerId) return;

  const decision = explain(actor, "org:delete", orgResource(org.id));
  throw new PermissionDeniedError("org:delete", {
    action: "org:delete",
    resourceKind: "organization",
    allowed: false,
    reason: decision.allowed ? "denied_by_role" : decision.reason,
  });
}

/**
 * The offer the actor may accept or decline, or a refusal. A lapsed offer is
 * not open: it does not surface, and acting on it changes nothing.
 */
async function actionableOffer(
  actor: Actor,
  orgId: OrgId,
  at: IsoTimestamp,
): Promise<OwnershipHandover> {
  const open = await handoverRepo.findOpenHandover(orgId, at);
  if (open) {
    if (open.toUserId !== actor.userId) {
      throw new OwnershipHandoverError("nothing_pending");
    }
    return open;
  }

  const latest = await handoverRepo.findLatestForUser(orgId, actor.userId);
  if (latest && latest.status === "pending" && latest.expiresAt <= at) {
    throw new OwnershipHandoverError("expired");
  }
  throw new OwnershipHandoverError("nothing_pending");
}

/**
 * Offers the workspace to another active member. One offer may be open at a
 * time; it lapses seven days after it is made.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const createdAt = now();
  if (await handoverRepo.findOpenHandover(orgId, createdAt)) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await handoverRepo.insertHandover({
    orgId,
    fromUserId: org.ownerId,
    toUserId,
    createdAt,
    expiresAt: addDays(createdAt, HANDOVER_WINDOW_DAYS),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You've been offered ownership of this workspace",
    body: "Accept to become the owner. The offer expires in seven days.",
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member becomes the recorded owner and holds the owner role. The
 * previous owner steps down to admin when they still hold the owner role.
 * Promotion happens before that demotion so the workspace never has no owner.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const at = now();
  const offer = await actionableOffer(actor, orgId, at);

  const acceptor = await memberRepo.findMember(orgId, actor.userId);
  if (!acceptor || acceptor.status !== "active") {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const previous = await memberRepo.findMember(orgId, offer.fromUserId);
  const roleChanges: { memberId: Member["id"]; from: Role; to: Role }[] = [];

  if (acceptor.role !== "owner") {
    await memberRepo.updateMemberRole(orgId, acceptor.id, "owner");
    roleChanges.push({
      memberId: acceptor.id,
      from: acceptor.role,
      to: "owner",
    });
  }

  await orgRepo.setOrgOwner(orgId, actor.userId);

  if (
    previous &&
    previous.userId !== acceptor.userId &&
    previous.role === "owner"
  ) {
    await memberRepo.updateMemberRole(orgId, previous.id, "admin");
    roleChanges.push({
      memberId: previous.id,
      from: previous.role,
      to: "admin",
    });
  }

  const resolved = await handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "accepted",
    at,
  );
  if (!resolved) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  for (const change of roleChanges) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: change.memberId,
      from: change.from,
      to: change.to,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: offer.fromUserId,
    toUserId: offer.toUserId,
  });

  return requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
}

/** The offered member turns the offer down. The workspace is unchanged. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const at = now();
  const offer = await actionableOffer(actor, orgId, at);
  const resolved = await handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "declined",
    at,
  );
  if (!resolved) throw new OwnershipHandoverError("nothing_pending");
  return resolved;
}

/** The recorded owner withdraws the open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  const at = now();
  const open = await handoverRepo.findOpenHandover(orgId, at);
  if (!open) throw new OwnershipHandoverError("nothing_pending");

  const resolved = await handoverRepo.resolveHandover(
    orgId,
    open.id,
    "canceled",
    at,
  );
  if (!resolved) throw new OwnershipHandoverError("nothing_pending");
  return resolved;
}

/** The open offer, or null when none is open. Visible to every member. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  return handoverRepo.findOpenHandover(orgId, now());
}

