 * synchronous turn so two callers cannot both observe "no offer".
 * Returns null when an open offer already exists.
 */
export async function insertHandover(input: {
  orgId: OrgId;
  fromUserId: UserId;
  toUserId: UserId;
  createdAt: IsoTimestamp;
  expiresAt: IsoTimestamp;
}): Promise<OwnershipHandover | null> {
  const db = getDb();
  const existing = db
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, input.orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, input.createdAt),
      ),
    )
    .get();
  if (existing) return null;

