let cleanup: () => void;
let detach: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

async function notificationsFor(tenant: Tenant, userId: UserId) {
  return notificationRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    limit: 20,
    cursor: null,
  });
}

describe("ownership handover", () => {
  it("offers, accepts, and follows the new owner", async () => {
    const tenant = await createTenant("handover-accept", "growth");
    const seen: unknown[] = [];
    const off = subscribe("organization.ownership_transferred", (payload) => {
      seen.push(payload);
    });
    const roles: unknown[] = [];
    const offRole = subscribe("member.role_changed", (payload) => {
      roles.push(payload);
    });

    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );

    expect(offer.status).toBe("pending");
    expect(offer.resolvedAt).toBeNull();
    expect(offer.fromUserId).toBe(tenant.userIds.owner);
    expect(offer.toUserId).toBe(tenant.userIds.member);
    expect(Date.parse(offer.expiresAt) - Date.parse(offer.createdAt)).toBe(
      7 * 24 * 60 * 60 * 1000,
    );

    const pending = await orgService.getPendingOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(pending?.id).toBe(offer.id);

    const memberNotes = await notificationsFor(tenant, tenant.userIds.member);
    expect(memberNotes.items.map((row) => row.kind)).toContain("ownership_handover");
    const ownerNotes = await notificationsFor(tenant, tenant.userIds.owner);
    expect(ownerNotes.items.map((row) => row.kind)).not.toContain("ownership_handover");
    const adminNotes = await notificationsFor(tenant, tenant.userIds.admin);
    expect(adminNotes.items.map((row) => row.kind)).not.toContain("ownership_handover");

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.admin,
      ),
    ).rejects.toMatchObject({ reason: "pending_exists" });

    await expect(
      orgService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const org = await orgService.acceptOwnershipHandover(
      tenant.actors.member,
      tenant.org.id,
    );
    off();
    offRole();

    expect(org.ownerId).toBe(tenant.userIds.member);
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    const previous = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(member?.role).toBe("owner");
    expect(previous?.role).toBe("admin");

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.member,
    });
    expect(roles).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          actorId: tenant.userIds.member,
          memberId: member?.id,
          from: "member",
          to: "owner",
        }),
        expect.objectContaining({
          actorId: tenant.userIds.member,
          memberId: previous?.id,
          from: "owner",
          to: "admin",
        }),
      ]),
    );

    const activity = await activityService.listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["organization.ownership_transferred"],
      limit: 10,
      cursor: null,
    });
    expect(activity.items[0]).toMatchObject({
      action: "organization.ownership_transferred",
      actorId: tenant.userIds.member,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: {
        fromUserId: tenant.userIds.owner,
        toUserId: tenant.userIds.member,
      },
    });

    expect(
      await orgService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).toBeNull();

    await expect(
      orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const next = await memberService.resolveActor(tenant.userIds.member, tenant.org.id);
    const prev = await memberService.resolveActor(tenant.userIds.owner, tenant.org.id);
    if (!next || !prev || !previous) throw new Error("actors missing");

    await expect(
      billingService.changePlan(prev, {
        orgId: tenant.org.id,
        plan: "enterprise",
        interval: "monthly",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const changed = await billingService.changePlan(next, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });
    expect(changed.plan).toBe("enterprise");

    const removed = await memberService.removeMember(next, {
      orgId: tenant.org.id,
      memberId: previous.id,
    });
    expect(removed.userId).toBe(tenant.userIds.owner);

    await emit("member.joined", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.viewer,
      occurredAt: toIsoTimestamp(new Date()),
      memberId: member!.id,
      userId: tenant.userIds.viewer,
      role: "viewer",
    });

    const joinedForNew = await notificationsFor(tenant, tenant.userIds.member);
    const joinedForOld = await notificationsFor(tenant, tenant.userIds.owner);
    expect(joinedForNew.items.map((row) => row.kind)).toContain("member_joined");
    expect(joinedForOld.items.map((row) => row.kind)).not.toContain("member_joined");
  });

  it("refuses anyone but the recorded owner, and refuses a bad target", async () => {
    const tenant = await createTenant("handover-guards", "growth");
    const other = await createTenant("handover-other", "growth");

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.admin,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const adminMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!adminMember) throw new Error("missing admin");
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: adminMember.id,
      role: "owner",
    });
    const secondOwner: Actor = {
      userId: tenant.userIds.admin,
      orgId: tenant.org.id,
      role: "owner",
    };
    await expect(
      orgService.initiateOwnershipHandover(
        secondOwner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.owner,
      ),
    ).rejects.toMatchObject({ reason: "self" });

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        "01HZZZNOBODYNOBODYNOBODY" as UserId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        other.userIds.member,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("missing viewer");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });
    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      orgService.initiateOwnershipHandover(
        tenant.actors.owner,
        other.org.id,
        other.userIds.member,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.owner, other.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("declines, withdraws, lapses, and withdraws when a side leaves", async () => {
    const declined = await createTenant("handover-decline", "growth");
    const offer = await orgService.initiateOwnershipHandover(
      declined.actors.owner,
      declined.org.id,
      declined.userIds.member,
    );
    const result = await orgService.declineOwnershipHandover(
      declined.actors.member,
      declined.org.id,
    );
    expect(result.status).toBe("declined");
    expect(result.resolvedAt).not.toBeNull();
    expect(result.id).toBe(offer.id);
    await expect(
      orgService.declineOwnershipHandover(declined.actors.member, declined.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
    const org = await orgService.getPendingOwnershipHandover(
      declined.actors.owner,
      declined.org.id,
    );
    expect(org).toBeNull();

    const withdrawn = await createTenant("handover-withdraw", "growth");
    await orgService.initiateOwnershipHandover(
      withdrawn.actors.owner,
      withdrawn.org.id,
      withdrawn.userIds.member,
    );
    await expect(
      orgService.cancelOwnershipHandover(withdrawn.actors.member, withdrawn.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    const canceled = await orgService.cancelOwnershipHandover(
      withdrawn.actors.owner,
      withdrawn.org.id,
    );
    expect(canceled.status).toBe("canceled");
    await expect(
      orgService.acceptOwnershipHandover(withdrawn.actors.member, withdrawn.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(
      orgService.cancelOwnershipHandover(withdrawn.actors.owner, withdrawn.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const lapsed = await createTenant("handover-lapse", "growth");
    const pending = await orgService.initiateOwnershipHandover(
      lapsed.actors.owner,
      lapsed.org.id,
      lapsed.userIds.member,
    );
    getDb()
      .update(ownershipHandovers)
      .set({ expiresAt: toIsoTimestamp(new Date()) })
      .where(eq(ownershipHandovers.id, pending.id))
      .run();

    expect(
      await orgService.getPendingOwnershipHandover(lapsed.actors.admin, lapsed.org.id),
    ).toBeNull();
    await expect(
      orgService.acceptOwnershipHandover(lapsed.actors.member, lapsed.org.id),
    ).rejects.toBeInstanceOf(OwnershipHandoverError);
    await expect(
      orgService.acceptOwnershipHandover(lapsed.actors.member, lapsed.org.id),
    ).rejects.toMatchObject({ reason: "expired" });
    await expect(
      orgService.declineOwnershipHandover(lapsed.actors.member, lapsed.org.id),
    ).rejects.toMatchObject({ reason: "expired" });
    await expect(
      orgService.cancelOwnershipHandover(lapsed.actors.owner, lapsed.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(
      orgService.acceptOwnershipHandover(lapsed.actors.admin, lapsed.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const again = await orgService.initiateOwnershipHandover(
      lapsed.actors.owner,
      lapsed.org.id,
      lapsed.userIds.admin,
    );
    expect(again.status).toBe("pending");
    const stored = await handoverRepo.findLatestForUser(
      lapsed.org.id,
      lapsed.userIds.member,
    );
    expect(stored?.status).toBe("pending");

    const left = await createTenant("handover-left", "growth");
    await orgService.initiateOwnershipHandover(
      left.actors.owner,
      left.org.id,
      left.userIds.member,
    );
    const target = await memberRepo.findMember(left.org.id, left.userIds.member);
    if (!target) throw new Error("missing target");
    await memberService.removeMember(left.actors.owner, {
      orgId: left.org.id,
      memberId: target.id,
    });
    expect(
      await orgService.getPendingOwnershipHandover(left.actors.owner, left.org.id),
    ).toBeNull();
    await expect(
      orgService.acceptOwnershipHandover(left.actors.member, left.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const ownerLeft = await createTenant("handover-owner-left", "growth");
    await orgService.initiateOwnershipHandover(
      ownerLeft.actors.owner,
      ownerLeft.org.id,
      ownerLeft.userIds.member,
    );
    const admin = await memberRepo.findMember(ownerLeft.org.id, ownerLeft.userIds.admin);
    const owner = await memberRepo.findMember(ownerLeft.org.id, ownerLeft.userIds.owner);
    if (!admin || !owner) throw new Error("missing");
    await memberService.updateMemberRole(ownerLeft.actors.owner, {
      orgId: ownerLeft.org.id,
      memberId: admin.id,
      role: "owner",
    });
    await memberService.removeMember(
      { userId: ownerLeft.userIds.admin, orgId: ownerLeft.org.id, role: "owner" },
      { orgId: ownerLeft.org.id, memberId: owner.id },
    );
    expect(
      await orgService.getPendingOwnershipHandover(
        ownerLeft.actors.member,
        ownerLeft.org.id,
      ),
    ).toBeNull();
  });

  it("does not change an owner who already holds the role, only the previous owner", async () => {
    const tenant = await createTenant("handover-already-owner", "growth");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!admin) throw new Error("missing");
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
      role: "owner",
    });

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    const roles: { memberId: string; from: string; to: string; actorId: string | null }[] = [];
    const off = subscribe("member.role_changed", (payload) => {
      roles.push(payload);
    });
    await orgService.acceptOwnershipHandover(
      { userId: tenant.userIds.admin, orgId: tenant.org.id, role: "owner" },
      tenant.org.id,
    );
    off();

    const previous = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    const next = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    expect(next?.role).toBe("owner");
    expect(previous?.role).toBe("admin");
    expect(roles).toHaveLength(1);
    expect(roles[0]).toMatchObject({
      actorId: tenant.userIds.admin,
      memberId: previous?.id,
      from: "owner",
      to: "admin",
    });
  });
});

